{
  "groups": [
    {
      "group_id": "high_rate_variable_pressure",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers on variable rates with high current interest costs are most sensitive to payment shock and active search for lower rates."
    },
    {
      "group_id": "stretched_young_families",
      "rule": "n_children >= 2 and household_income_cad < 75000 and has_savings == False",
      "rationale": "Low income households with multiple children and no liquidity buffers represent a high churn risk due to potential financial distress."
    },
    {
      "group_id": "equity_rich_stable_renewers",
      "rule": "mortgage_balance_cad < 350000 and credit_score_band == '720_plus' and has_investments == True",
      "rationale": "High credit, wealthy, and low-balance borrowers are prime targets for competitors but often seek simplicity and relationship-based retention."
    },
    {
      "group_id": "recent_purchase_fixed_lock",
      "rule": "origination_year >= 2022 and rate_type == 'fixed' and mortgage_rate_pct >= 4.0",
      "rationale": "Borrowers who bought at the peak of the rate cycle are likely to have negative equity or high LTV concerns, making them prone to seeking mortgage portability or restructuring."
    },
    {
      "group_id": "distressed_credit_segment",
      "rule": "credit_score_band == 'below_600' or credit_score_band == '600_659'",
      "rationale": "Borrowers with lower credit scores have limited options for refinancing elsewhere and are more dependent on current lender support."
    },
    {
      "group_id": "life_event_driven",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Major personal transitions often trigger re-evaluation of household debt structures and external lender shopping."
    },
    {
      "group_id": "self_employed_complex_needs",
      "rule": "employment_status == 'self_employed' and mortgage_balance_cad > 450000",
      "rationale": "Self-employed individuals with large balances require specialized retention efforts due to their complex income verification needs compared to standard payroll employees."
    },
    {
      "group_id": "long_tenure_legacy_low_rate",
      "rule": "td_tenure_months > 80 and mortgage_rate_pct < 3.0",
      "rationale": "Long-term loyal customers currently benefiting from very low rates will face significant payment increases, increasing their propensity to switch upon renewal."
    }
  ]
}
